1	import { create } from "@bufbuild/protobuf";
2	import { FieldMaskSchema, timestampDate, timestampFromDate } from "@bufbuild/protobuf/wkt";
3	import { isEqual } from "lodash-es";
4	import { memoServiceClient } from "@/connect";
5	import type { Attachment } from "@/types/proto/api/v1/attachment_service_pb";
6	import { AttachmentSchema } from "@/types/proto/api/v1/attachment_service_pb";
7	import type { Memo } from "@/types/proto/api/v1/memo_service_pb";
8	import { MemoSchema } from "@/types/proto/api/v1/memo_service_pb";
9	import type { EditorState } from "../state";
10	import { uploadService } from "./uploadService";
11	
12	/**
13	 * Converts attachments to reference format for API requests.
14	 * The backend only needs the attachment name to link it to a memo.
15	 */
16	function toAttachmentReferences(attachments: Attachment[]): Attachment[] {
17	  return attachments.map((a) => create(AttachmentSchema, { name: a.name }));
18	}
19	
20	function buildUpdateMask(
21	  prevMemo: Memo,
22	  state: EditorState,
23	  allAttachments: typeof state.metadata.attachments,
24	): { mask: Set<string>; patch: Partial<Memo> } {
25	  const mask = new Set<string>();
26	  const patch: Partial<Memo> = {
27	    name: prevMemo.name,
28	    content: state.content,
29	  };
30	
31	  if (!isEqual(state.content, prevMemo.content)) {
32	    mask.add("content");
33	    patch.content = state.content;
34	  }
35	  if (!isEqual(state.metadata.visibility, prevMemo.visibility)) {
36	    mask.add("visibility");
37	    patch.visibility = state.metadata.visibility;
38	  }
39	  if (!isEqual(allAttachments, prevMemo.attachments)) {
40	    mask.add("attachments");
41	    patch.attachments = toAttachmentReferences(allAttachments);
42	  }
43	  if (!isEqual(state.metadata.relations, prevMemo.relations)) {
44	    mask.add("relations");
45	    patch.relations = state.metadata.relations;
46	  }
47	  if (!isEqual(state.metadata.location, prevMemo.location)) {
48	    mask.add("location");
49	    patch.location = state.metadata.location;
50	  }
51	
52	  // Auto-update timestamp if content changed
53	  if (["content", "attachments", "relations", "location"].some((key) => mask.has(key))) {
54	    mask.add("update_time");
55	  }
56	
57	  // Handle custom timestamps
58	  if (state.timestamps.createTime) {
59	    const prevCreateTime = prevMemo.createTime ? timestampDate(prevMemo.createTime) : undefined;
60	    if (!isEqual(state.timestamps.createTime, prevCreateTime)) {
61	      mask.add("create_time");
62	      patch.createTime = timestampFromDate(state.timestamps.createTime);
63	    }
64	  }
65	  if (state.timestamps.updateTime) {
66	    const prevUpdateTime = prevMemo.updateTime ? timestampDate(prevMemo.updateTime) : undefined;
67	    if (!isEqual(state.timestamps.updateTime, prevUpdateTime)) {
68	      mask.add("update_time");
69	      patch.updateTime = timestampFromDate(state.timestamps.updateTime);
70	    }
71	  }
72	
73	  return { mask, patch };
74	}
75	
76	export const memoService = {
77	  async save(
78	    state: EditorState,
79	    options: {
80	      memoName?: string;
81	      parentMemoName?: string;
82	    },
83	  ): Promise<{ memoName: string; hasChanges: boolean }> {
84	    // 1. Upload local files first
85	    const newAttachments = await uploadService.uploadFiles(state.localFiles);
86	    const allAttachments = [...state.metadata.attachments, ...newAttachments];
87	
88	    // 2. Update existing memo
89	    if (options.memoName) {
90	      const prevMemo = await memoServiceClient.getMemo({ name: options.memoName });
91	      const { mask, patch } = buildUpdateMask(prevMemo, state, allAttachments);
92	
93	      if (mask.size === 0) {
94	        return { memoName: prevMemo.name, hasChanges: false };
95	      }
96	
97	      const memo = await memoServiceClient.updateMemo({
98	        memo: create(MemoSchema, patch as Record<string, unknown>),
99	        updateMask: create(FieldMaskSchema, { paths: Array.from(mask) }),
100	      });
101	      return { memoName: memo.name, hasChanges: true };
102	    }
103	
104	    // 3. Create new memo or comment
105	    const memoData = create(MemoSchema, {
106	      content: state.content,
107	      visibility: state.metadata.visibility,
108	      attachments: toAttachmentReferences(allAttachments),
109	      relations: state.metadata.relations,
110	      location: state.metadata.location,
111	      createTime: state.timestamps.createTime ? timestampFromDate(state.timestamps.createTime) : undefined,
112	      updateTime: state.timestamps.updateTime ? timestampFromDate(state.timestamps.updateTime) : undefined,
113	    });
114	
115	    const memo = options.parentMemoName
116	      ? await memoServiceClient.createMemoComment({
117	          name: options.parentMemoName,
118	          comment: memoData,
119	        })
120	      : await memoServiceClient.createMemo({ memo: memoData });
121	
122	    return { memoName: memo.name, hasChanges: true };
123	  },
124	
125	  /**
126	   * Build the INIT_MEMO payload from an already-loaded Memo entity (no network
127	   * request). Returns only the fields the reducer's INIT_MEMO case consumes —
128	   * UI state (mode, loading flags, …) is owned by the reducer, not by memos.
129	   */
130	  fromMemo(memo: Memo): Pick<EditorState, "content" | "metadata" | "timestamps"> {
131	    return {
132	      content: memo.content,
133	      metadata: {
134	        visibility: memo.visibility,
135	        attachments: memo.attachments,
136	        relations: memo.relations,
137	        location: memo.location,
138	      },
139	      timestamps: {
140	        createTime: memo.createTime ? timestampDate(memo.createTime) : undefined,
141	        updateTime: memo.updateTime ? timestampDate(memo.updateTime) : undefined,
142	      },
143	    };
144	  },
145	};
